  coach: [['overview','⌂','Overview'],['athletes','⌕','Athletes'],['videos','▷','Training hub'],['community','◉','Community'],['messages','✉','Messages'],['profile','◎','My profile']],
  donor: [['overview','⌂','Overview'],['athletes','⌕','Athletes'],['support','♡','Support requests'],['leaderboard','↗','Leaderboard'],['community','◉','Community'],['messages','✉','Messages'],['profile','◎','My profile']],
  judge: [['overview','⌂','Overview'],['results','🏅','Submit tournament result']],
